package com.proxyslabs.haruna.image
import java.io.File
fun main(args:Array<String>){val root=File(args[1]).apply{mkdirs()};try{val start=System.nanoTime();val dir=File(args[0]).inputStream().use{NezumiPackage.install(it,root,{false},{root.usableSpace},{}){NezumiImageNative.validateFiles(NezumiPackage.graphFiles(it))}};val manifest=ImagePackage.verify(dir);check(manifest.getString("format")==NezumiPackage.format);val handle=NezumiImageNative.create();try{check(NezumiImageNative.loadCpu(handle,dir.path)){NezumiImageNative.lastError()};check(NezumiImageNative.isLoaded(handle));NezumiImageNative.unload(handle);check(!NezumiImageNative.isLoaded(handle))}finally{NezumiImageNative.destroy(handle)};println("REAL IMPORT + SHA restore + CPU load/unload PASS: "+manifest.getString("displayName")+" seconds="+(System.nanoTime()-start)/1e9)}finally{root.deleteRecursively()}}
